/// <summary>
/// Service class to process the excise claims for free items.
/// </summary>
public class METFreeItemExciseClaimService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// process the Service request
    /// </summary>
    /// <param name = "_dataContract">Data contract</param>
    public void processOperation(METFreeItemExciseClaimContract _dataContract)
    {
        METFreeItemExciseClaimContract  dataContract;

        InventSiteId siteid = dataContract.parmSiteId();

        Query query = new Query(queryStr(METFreeItemExciseClaimBaseQuery));
        if(siteid)
        {
            QueryBuildDataSource qbdsInventSite = query.dataSourceTable(tableNum(InventSite));
            qbdsInventSite.addRange(fieldNum(InventSite, SiteId)).value(SysQuery::value(siteid));
        }

        QueryRun qr = new QueryRun(query);

        RecordInsertList claimRegisterList = new RecordInsertList(tableNum(METVendorClaimRegister));
        container custInvoiceTransRecIdCon;
        
        while(qr.next())
        {
            CustInvoiceTrans        custInvoiceTrans = qr.get(tableNum(CustInvoiceTrans));
            InventSite              inventSite = qr.get(tableNum(InventSite));
            ReqItemTable            reqItemTable = qr.get(tableNum(ReqItemTable));
            RetailSalesDiscountLine retailSalesDiscountLine = qr.get(tableNum(RetailSalesDiscountLine));
            METExciseSiteDutySetup  siteSpecificDuty = qr.get(tableNum(METExciseSiteDutySetup));

            METVendorClaimRegister          metVendorClaimRegister;
            metVendorClaimRegister.ClaimLineId      =   this.getClaimLineIdNumberSeq().num();
            metVendorClaimRegister.UnitClaimAmount  =   siteSpecificDuty.ValueForDuty;
            metVendorClaimRegister.ClaimAmount      =   siteSpecificDuty.ValueForDuty * custInvoiceTrans.Qty; //To be updated based on Duty role build
            metVendorClaimRegister.DiscountId       =   retailSalesDiscountLine.PeriodicDiscountOfferId;
            metVendorClaimRegister.VendAccount      =   reqItemTable.VendId;
            metVendorClaimRegister.ClaimType        =   METVendorClaimType::FreeItemExcise;
            metVendorClaimRegister.CustAccount      =   custInvoiceTrans.invoiceAccount();
            metVendorClaimRegister.ItemId           =   custInvoiceTrans.ItemId;
            metVendorClaimRegister.ItemDescription  =   custInvoiceTrans.itemName();
            metVendorClaimRegister.Qty              =   custInvoiceTrans.Qty;
            metVendorClaimRegister.UnitId           =   custInvoiceTrans.SalesUnit;
            metVendorClaimRegister.SiteId           =   inventSite.SiteId;
            metVendorClaimRegister.ClaimStatus      =   METVendorClaimStatus::Approved;

            claimRegisterList.add(metVendorClaimRegister);

            //store the CustInvoiceTrans RecID to update the status to Processed
            
            custInvoiceTransRecIdCon += CustInvoiceTrans.RecId;
        }

        if(conLen(custInvoiceTransRecIdCon) > 0)
        {
            try
            {
                ttsbegin;
                claimRegisterList.insertDatabase();
                this.updateCustInvoiceTransStatus(custInvoiceTransRecIdCon);
                ttscommit;
            }
            catch(Exception::DuplicateKeyException)
            {
                Error("@MET:METVendClaimRegDuplicateKeyException");
                throw Exception::DuplicateKeyExceptionNotRecovered;
            }
            catch(Exception::Error)
            {
                Error("@MET:METVendClaimRegErrorException");
            }
        }
    }

    private NumberSeq getClaimLineIdNumberSeq()
    {
        NumberSequenceReference numberSequenceReference;
        NumberSequenceTable     numberSequenceTable;
        NumberSeq               numberSeq;

        numberSequenceReference = GUPParameters::numRefMETVendClaimLineId();
        numberSequenceTable = NumberSequenceTable::find(numberSequenceReference.NumberSequenceId);

        if (numberSequenceTable)
        {
            if (numberSequenceTable.Manual == NoYes::Yes)
            {
                throw error(strFmt("@SYS131762", "@MET:VendorClaimLineId"));
            }
            else
            {
                numberSeq = NumberSeq::newGetNum(numberSequenceReference);
            }
        }

        if (numberSeq == null)
        {
            throw error(strfmt("@GLS111556", new DictType(extendedtypenum(METVendClaimLineId)).label(), "@GlobalUnifiedPricing:GUPParameters"));
        }

        return numberSeq;
    }

    public void updateCustInvoiceTransStatus(container _custInvoiceTransRecIdCon)
    {
        str invoiceClaimProcessedStatus = enum2Str(METFreeItemExciseVendClaimStatus::Processed);
        str range = con2str(_custInvoiceTransRecIdCon);

        Query query = new Query();
        QueryBuildDataSource qbdCustInvoiceTrans = query.addDataSource(tableNum(CustInvoiceTrans));
        qbdCustInvoiceTrans.addRange(fieldnum(CustInvoiceTrans,RecId)).value(range);

        Map fieldSetMap = new Map(Types::String, Types::String);
        fieldSetMap.insert(fieldStr(CustInvoiceTrans, METFreeItemExciseVendClaimStatus), invoiceClaimProcessedStatus);

        Query::update_recordset(fieldSetMap, query);
    }
